        roadways = [
            (u, v, key)
            for u, v, key, data in G.edges(node, keys=True, data=True)
            if not data.get("ugv_sidewalk")
        ]
        if len(roadways) > 2:
            G.nodes[node]["ugv_intersection"] = True
